var INV_CONTEUDO_MODULO = "<style>\n/* Variáveis de cor do módulo — faltavam (--accent, --accent-2, --input,\n   --panel, --shadow-soft, --text-strong, --muted-2), causando texto sem\n   contraste e cartões sem fundo em toda a tela (bug real encontrado em\n   2026-08-21, mesmo problema do PGT e POP/CronExec/RegOp). As demais\n   (--bg, --text, --border etc.) já vêm do tema global do Portal. */\n#tplInvContainer {\n  --accent: var(--bc-action);\n  --accent-2: var(--bc-action);\n  --input: #FFFFFF;\n  --panel: var(--bc-surface);\n  --shadow-soft: none;\n  --text-strong: var(--bc-text);\n  --muted-2: var(--bc-text-3);\n  --surface-2: var(--bc-surface-2);\n}\n#tplInvContainer, #tplInvContainer body {\n  font-family: var(--bc-sans);\n}\n#tplInvContainer * { box-sizing: border-box; }\n#tplInvContainer .wrap { max-width: 100%; margin: 0; padding: 18px; }\n#tplInvContainer .header-card {\n  background: #FFFFFF;\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  padding: 14px 18px;\n  box-shadow: var(--shadow-soft);\n  margin-bottom: 14px;\n}\n#tplInvContainer .header-card h1 { margin: 0; font-size: 19px; color: var(--text-strong); font-weight: 800; }\n#tplInvContainer .header-card p { margin: 5px 0 0; color: var(--muted); font-size: 13px; }\n#tplInvContainer .panel {\n  background: #FFFFFF;\n  border-radius: var(--radius); padding: 18px; box-shadow: var(--shadow-soft); border: 1px solid var(--border);\n  margin-bottom: 14px;\n}\n#tplInvContainer .inv-filters-grid { display: grid; grid-template-columns: 1fr 1fr 1fr 1fr auto; gap: 12px; align-items: end; }\n#tplInvContainer .form-group label { display: block; margin-bottom: 6px; font-size: 12px; font-weight: 700; color: var(--text); }\n#tplInvContainer .form-control {\n  width: 100%; min-height: 30px; padding: 5px 9px; border: 1px solid var(--border); border-radius: var(--radius-sm);\n  font-size: 12.5px; color: var(--text); background: var(--input);\n}\n#tplInvContainer .btn {\n  padding: 7px 14px; border: 1px solid transparent; border-radius: var(--radius-sm); font-weight: 800;\n  font-size: 12.5px; cursor: pointer; min-height: 30px; white-space: nowrap;\n}\n#tplInvContainer .btn:disabled { opacity: 0.55; cursor: not-allowed; }\n#tplInvContainer .btn-primary { background: var(--accent); color: var(--text-strong); }\n#tplInvContainer .btn-secondary { background: var(--card-soft); color: var(--text-strong); border: 1px solid var(--border); }\n\n#tplInvContainer .inv-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; margin-bottom: 14px; }\n#tplInvContainer .inv-kpi {\n  background: var(--card); border: 1px solid var(--border); border-radius: var(--radius-sm);\n  padding: 12px 14px; text-align: center; border-top: 3px solid var(--border);\n}\n#tplInvContainer .inv-kpi-total  { border-top-color: var(--accent-2); }\n#tplInvContainer .inv-kpi-ok     { border-top-color: var(--success); }\n#tplInvContainer .inv-kpi-warn   { border-top-color: var(--warning); }\n#tplInvContainer .inv-kpi-danger { border-top-color: var(--danger); }\n#tplInvContainer .inv-kpi-muted  { border-top-color: var(--muted-2); }\n#tplInvContainer .inv-kpi-value  { font-size: 22px; font-weight: 800; color: var(--text-strong); line-height: 1.1; margin-bottom: 4px; }\n#tplInvContainer .inv-kpi-label  { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .3px; }\n#tplInvContainer .inv-kpi-sub    { font-size: 11px; color: var(--muted); margin-top: 2px; }\n\n#tplInvContainer .inv-action-bar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; flex-wrap: wrap; gap: 10px; }\n#tplInvContainer .inv-action-bar-right { font-size: 12px; color: var(--muted); }\n\n#tplInvContainer table.tbl { width: 100%; border-collapse: collapse; font-size: 12px; }\n#tplInvContainer table.tbl th, #tplInvContainer table.tbl td { border-bottom: 1px solid var(--border); padding: 6px 8px; text-align: left; vertical-align: middle; }\n#tplInvContainer table.tbl th { background: var(--card-soft); color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: .3px; }\n#tplInvContainer table.tbl tr.inv-row-vencido td  { background: var(--bc-danger-bg); }\n#tplInvContainer table.tbl tr.inv-row-vencendo td { background: var(--bc-warn-bg); }\n#tplInvContainer table.tbl tr.inv-row-inativo td  { opacity: .6; }\n\n#tplInvContainer .inv-badge { display: inline-block; padding: 2px 8px; border-radius: 20px; font-size: 10.5px; font-weight: 800; white-space: nowrap; }\n#tplInvContainer .inv-badge-ok       { background: var(--bc-action-bg); color: var(--success); }\n#tplInvContainer .inv-badge-vencendo { background: var(--bc-warn-bg); color: var(--warning); }\n#tplInvContainer .inv-badge-vencido  { background: var(--bc-danger-bg); color: var(--danger); }\n#tplInvContainer .inv-badge-semdoc   { background: var(--card-soft); color: var(--muted); }\n#tplInvContainer .badge-ativo   { background: var(--bc-action-bg); color: var(--success); padding:2px 8px;border-radius:20px;font-size:10.5px;font-weight:800; }\n#tplInvContainer .badge-inativo { background: var(--card-soft); color: var(--muted); padding:2px 8px;border-radius:20px;font-size:10.5px;font-weight:800; }\n\n#tplInvContainer .inv-loading, #tplInvContainer .inv-empty { padding: 40px; text-align: center; color: var(--muted); font-size: 13px; }\n\n/* ================================================\n   IMPRESSÃO — OVERLAY (papel branco, igual aos outros documentos do sistema)\n================================================ */\n#tplInv-print-overlay {\n  display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%;\n  background: #ffffff; z-index: 9999; overflow: auto;\n}\n/* ================================================\n   MANUAL DO OPERADOR — OVERLAY (mesmo mecanismo do overlay de impressão)\n================================================ */\n#tplInv-manual-overlay {\n  display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%;\n  background: var(--bc-bg); z-index: 9999; overflow: auto;\n}\n.tplInv-manual-toolbar {\n  position: sticky; top: 0; background: #FFFFFF; color: var(--bc-text); padding: 10px 24px;\n  display: flex; justify-content: space-between; align-items: center; z-index: 10;\n  box-shadow: 0 2px 8px rgba(28,31,29,0.1);\n}\n.tplInv-manual-toolbar-title { font-size: 15px; font-weight: 700; }\n.tplInv-manual-toolbar button { padding: 8px 20px; border-radius: 6px; font-weight: 700; font-size: 13px; cursor: pointer; border: none; background: #fff; color: #1f2937; }\n#tplInv-manual-overlay .manual-wrap { max-width: 900px; margin: 0 auto; padding: 18px 18px 60px; line-height: 1.6; color: var(--text, var(--bc-text)); }\n#tplInv-manual-overlay .manual-wrap h1 { font-size: 26px; margin-bottom: 4px; color: var(--text-strong, var(--bc-text)); }\n#tplInv-manual-overlay .manual-wrap h2 { font-size: 19px; margin-top: 40px; padding-bottom: 8px; border-bottom: 1px solid var(--border, var(--bc-line)); color: var(--text-strong, var(--bc-text)); }\n#tplInv-manual-overlay .manual-wrap p { color: var(--text, var(--bc-text)); }\n#tplInv-manual-overlay .manual-wrap table { width: 100%; border-collapse: collapse; margin: 14px 0 22px; font-size: 13.5px; }\n#tplInv-manual-overlay .manual-wrap th, #tplInv-manual-overlay .manual-wrap td { border: 1px solid var(--border, var(--bc-line)); padding: 8px 10px; text-align: left; vertical-align: top; }\n#tplInv-manual-overlay .manual-wrap th { background: #FFFFFF; color: var(--text-strong, var(--bc-text)); }\n#tplInv-manual-overlay .manual-wrap tr:nth-child(even) td { background: var(--bc-surface-2); }\n#tplInv-manual-overlay .callout { background: var(--bc-action-bg); border: 1px solid var(--bc-action-line); border-left: 4px solid var(--accent, var(--bc-brand)); border-radius: 6px; padding: 12px 14px; margin: 14px 0; font-size: 13.5px; }\n#tplInv-manual-overlay .callout strong { color: var(--text-strong, var(--bc-text)); }\n#tplInv-manual-overlay .manual-wrap ol, #tplInv-manual-overlay .manual-wrap ul { padding-left: 22px; }\n#tplInv-manual-overlay .manual-wrap ol li, #tplInv-manual-overlay .manual-wrap ul li { margin-bottom: 6px; }\n#tplInv-manual-overlay .toc { background: var(--panel, #FFFFFF); border: 1px solid var(--border, var(--bc-line)); border-radius: 8px; padding: 16px 20px; margin-bottom: 30px; }\n#tplInv-manual-overlay .toc h2 { margin-top: 0; border-bottom: none; font-size: 15px; }\n#tplInv-manual-overlay .toc ol { columns: 2; column-gap: 30px; }\n#tplInv-manual-overlay .toc a { text-decoration: none; color: var(--accent-2, var(--bc-info)); cursor: pointer; }\n#tplInv-manual-overlay .toc a:hover { text-decoration: underline; }\n#tplInv-manual-overlay .topo-link { display: inline-block; margin-top: 30px; color: var(--accent-2, var(--bc-info)); cursor: pointer; }\n.tplInv-print-toolbar {\n  position: sticky; top: 0; background: #1f2937; color: #fff; padding: 10px 24px;\n  display: flex; justify-content: space-between; align-items: center; z-index: 10;\n  box-shadow: 0 2px 8px rgba(0,0,0,.3);\n}\n.tplInv-print-toolbar-title { font-size: 15px; font-weight: 700; }\n.tplInv-print-toolbar-actions { display: flex; gap: 10px; }\n.tplInv-print-toolbar-actions button { padding: 8px 20px; border-radius: 6px; font-weight: 700; font-size: 13px; cursor: pointer; border: none; }\n.btn-tplInv-print { background: #22c55e; color: #fff; }\n.btn-tplInv-close { background: #fff; color: #1f2937; }\n.tplInv-print-scale-outer { width: 100%; overflow: hidden; box-sizing: border-box; padding: 24px 0 24px 16px; }\n.tplInv-print-page-wrap { width: 297mm; margin: 0; padding: 10mm 12mm; transform-origin: top left; box-shadow: 0 2px 14px rgba(0,0,0,.18); }\n\n.tplInv-prt-doc { background: #fff; font-family: 'Segoe UI',Arial, sans-serif; font-size: 10pt; color: #111; padding: 0; box-shadow: none; }\n.tplInv-prt-header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #007b3e; padding-bottom: 10px; margin-bottom: 12px; }\n.tplInv-prt-brand-name { font-size: 16pt; font-weight: 900; color: #007b3e; letter-spacing: .5px; }\n.tplInv-prt-brand-slogan { font-size: 8pt; color: #555; margin-top: 2px; }\n.tplInv-prt-header-doc { text-align: right; }\n.tplInv-prt-doc-title { font-size: 13pt; font-weight: 800; color: #1a2e5a; text-transform: uppercase; letter-spacing: .5px; }\n.tplInv-prt-doc-sub { font-size: 8pt; color: #555; margin-top: 2px; }\n\n.tplInv-prt-meta-box { background: #f8f9fa; border: 1px solid #e2e8f0; border-radius: 6px; padding: 10px 14px; margin-bottom: 14px; display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px 10px; }\n.tplInv-prt-meta-key { font-size: 7.5pt; font-weight: 700; color: #666; text-transform: uppercase; letter-spacing: .3px; }\n.tplInv-prt-meta-val { font-size: 9.5pt; font-weight: 600; color: #111; }\n\n.tplInv-prt-section-title { font-size: 8pt; font-weight: 800; color: #1a2e5a; text-transform: uppercase; letter-spacing: .8px; border-left: 3px solid #007b3e; padding-left: 7px; margin: 14px 0 8px; }\n\n.tplInv-prt-kpis { display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px; margin-bottom: 6px; }\n.tplInv-prt-kpi { border: 1px solid #e2e8f0; border-radius: 6px; padding: 8px 6px; text-align: center; border-top: 3px solid; }\n.tplInv-prt-kpi-total   { border-top-color: #1a56db; }\n.tplInv-prt-kpi-ok1     { border-top-color: #16a34a; }\n.tplInv-prt-kpi-ok2     { border-top-color: #0891b2; }\n.tplInv-prt-kpi-warn    { border-top-color: #d97706; }\n.tplInv-prt-kpi-danger  { border-top-color: #dc2626; }\n.tplInv-prt-kpi-gray    { border-top-color: #9ca3af; }\n.tplInv-prt-kpi-value { font-size: 18pt; font-weight: 900; line-height: 1; margin-bottom: 3px; }\n.tplInv-prt-kpi-total  .tplInv-prt-kpi-value { color: #1a56db; }\n.tplInv-prt-kpi-ok1    .tplInv-prt-kpi-value { color: #16a34a; }\n.tplInv-prt-kpi-ok2    .tplInv-prt-kpi-value { color: #0891b2; }\n.tplInv-prt-kpi-warn   .tplInv-prt-kpi-value { color: #d97706; }\n.tplInv-prt-kpi-danger .tplInv-prt-kpi-value { color: #dc2626; }\n.tplInv-prt-kpi-gray   .tplInv-prt-kpi-value { color: #6b7280; }\n.tplInv-prt-kpi-label { font-size: 6.5pt; font-weight: 700; color: #555; text-transform: uppercase; letter-spacing: .3px; }\n\n.tplInv-prt-table { width: 100%; border-collapse: collapse; font-size: 7.5pt; }\n.tplInv-prt-table thead tr { background: #1a2e5a; color: #fff; }\n.tplInv-prt-table th { padding: 5px 6px; text-align: left; font-weight: 700; font-size: 7pt; text-transform: uppercase; letter-spacing: .3px; white-space: nowrap; }\n.tplInv-prt-table td { padding: 4px 6px; border-bottom: 1px solid #f0f0f0; vertical-align: middle; }\n.tplInv-prt-table tbody tr:nth-child(even) td { background: #f9fafb; }\n.tplInv-prt-row-vencido  td { background: #fff0f0 !important; }\n.tplInv-prt-row-vencendo td { background: #fffbeb !important; }\n.tplInv-prt-row-inativo  td { opacity: .6; }\n.tplInv-prt-tag { font-weight: 800; font-size: 8pt; color: #1a2e5a; }\n.tplInv-prt-tipo { font-weight: 600; }\n.tplInv-prt-badge { display: inline-block; padding: 1px 5px; border-radius: 8px; font-size: 6.5pt; font-weight: 700; white-space: nowrap; }\n.tplInv-prt-badge-ok      { background: #d1fae5; color: #065f46; }\n.tplInv-prt-badge-vencendo{ background: #fef3c7; color: #92400e; }\n.tplInv-prt-badge-vencido { background: #fee2e2; color: #991b1b; }\n.tplInv-prt-badge-semdoc  { background: #f3f4f6; color: #6b7280; }\n.tplInv-prt-badge-ativo   { background: #d1fae5; color: #065f46; }\n.tplInv-prt-badge-inativo { background: #f3f4f6; color: #6b7280; }\n.tplInv-prt-footer-brand { font-weight: 700; color: #007b3e; }\n\n@media print {\n  @page { size: A4 landscape; margin: 10mm 12mm; }\n  html, body { background: #fff !important; }\n  body.tplInv-printing > *:not(#tplInv-print-overlay) { display: none !important; }\n  body.tplInv-printing #tplInv-print-overlay { position: static; width: 100%; background: white; overflow: visible; display: block !important; }\n  .tplInv-print-toolbar { display: none !important; }\n  .tplInv-print-page-wrap { max-width: 100%; width: auto; margin: 0; padding: 0; transform: none !important; box-shadow: none !important; }\n  .tplInv-print-scale-outer { width: auto; overflow: visible; height: auto !important; padding: 0 !important; }\n  .tplInv-prt-doc { box-shadow: none; padding: 0; }\n  .tplInv-prt-table { page-break-inside: auto; }\n  .tplInv-prt-table tr { page-break-inside: avoid; }\n  .tplInv-prt-table thead { display: table-header-group; }\n}\n@media (max-width: 900px) {\n  #tplInvContainer .inv-filters-grid { grid-template-columns: 1fr 1fr; }\n}\n</style>\n\n<script>\nvar INV_STATE = { dados: null, clientes: [], unidades: [] };\n\nfunction tplInv_escapeHtml_(v) {\n  return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');\n}\n\nfunction tplInv_root_() { return document.getElementById('tplInv_root'); }\n\nfunction tplInv_renderReal_() {\n  var container = document.getElementById('tplInvContainer');\n  if (!container) return;\n  container.innerHTML = '<div class=\"wrap\"><div id=\"tplInv_root\"></div></div>';\n  tplInv_garantirOverlay_();\n  tplInv_garantirManualOverlay_();\n  tplInv_irParaTela_();\n}\n\nfunction tplInv_garantirManualOverlay_() {\n  if (document.getElementById('tplInv-manual-overlay')) return;\n  var div = document.createElement('div');\n  div.id = 'tplInv-manual-overlay';\n  div.innerHTML =\n    '<div class=\"tplInv-manual-toolbar\">' +\n      '<span class=\"tplInv-manual-toolbar-title\">Manual do Operador — Inventário de Equipamentos</span>' +\n      '<button onclick=\"tplInv_fecharManual_()\">← Voltar ao sistema</button>' +\n    '</div>' +\n    tplInv_manualHtml_();\n  document.body.appendChild(div);\n}\n\nfunction tplInv_abrirManual_() {\n  tplInv_garantirManualOverlay_();\n  var overlay = document.getElementById('tplInv-manual-overlay');\n  if (overlay) overlay.style.display = 'block';\n}\n\nfunction tplInv_fecharManual_() {\n  var overlay = document.getElementById('tplInv-manual-overlay');\n  if (overlay) overlay.style.display = 'none';\n}\n\nfunction tplInv_irParaSecaoManual_(id) {\n  var el = document.getElementById(id);\n  if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'start' });\n}\n\nfunction tplInv_manualHtml_() {\n  return `\n<div class=\"wrap manual-wrap\">\n\n  <div class=\"toc\" id=\"tplInv_topoManual\">\n    <h2>Índice</h2>\n    <ol>\n      <li><a onclick=\"tplInv_irParaSecaoManual_('tplInv_ms1')\">Como usar este manual</a></li>\n      <li><a onclick=\"tplInv_irParaSecaoManual_('tplInv_ms2')\">O que este sistema faz</a></li>\n      <li><a onclick=\"tplInv_irParaSecaoManual_('tplInv_ms3')\">Filtros</a></li>\n      <li><a onclick=\"tplInv_irParaSecaoManual_('tplInv_ms4')\">Gerar Inventário</a></li>\n      <li><a onclick=\"tplInv_irParaSecaoManual_('tplInv_ms5')\">Entendendo a tabela e os status</a></li>\n      <li><a onclick=\"tplInv_irParaSecaoManual_('tplInv_ms6')\">Gerar PDF / Imprimir</a></li>\n      <li><a onclick=\"tplInv_irParaSecaoManual_('tplInv_ms7')\">Salvar no Drive e Documentos já Gerados</a></li>\n      <li><a onclick=\"tplInv_irParaSecaoManual_('tplInv_ms8')\">Passo a passo completo</a></li>\n      <li><a onclick=\"tplInv_irParaSecaoManual_('tplInv_ms9')\">Erros comuns</a></li>\n      <li><a onclick=\"tplInv_irParaSecaoManual_('tplInv_ms10')\">Glossário</a></li>\n    </ol>\n  </div>\n\n  <h2 id=\"tplInv_ms1\">1. Como usar este manual</h2>\n  <p>Este manual foi escrito para quem <strong>nunca usou o sistema</strong>. Leia na ordem, de cima para baixo. Se aparecer uma palavra técnica desconhecida, vá direto ao <strong>Glossário</strong> (seção 10).</p>\n\n  <h2 id=\"tplInv_ms2\">2. O que este sistema faz, em uma frase</h2>\n  <p>Este módulo <strong>não cadastra nada novo</strong> — ele lê o que já existe no cadastro de clientes/equipamentos/documentos do Portal e monta um <strong>relatório gerencial</strong>: todos os equipamentos de um cliente (ou de todos os clientes), com o status de calibração e qualificação de cada um, pronto pra imprimir ou salvar em PDF.</p>\n  <div class=\"callout\"><strong>Isto é um retrato do momento em que você gera o inventário.</strong> Se um documento vencer amanhã, o inventário gerado hoje não atualiza sozinho — gere de novo quando precisar de um retrato atualizado.</div>\n\n  <h2 id=\"tplInv_ms3\">3. Filtros</h2>\n  <table>\n    <tr><th>Campo</th><th>O que fazer</th></tr>\n    <tr><td>Buscar por CNPJ</td><td>Digite e clique em \"Buscar\" (ou aperte Enter) pra localizar um cliente específico direto pelo CNPJ</td></tr>\n    <tr><td>Cliente</td><td>Escolha um cliente específico, ou deixe em \"Todos os clientes\"</td></tr>\n    <tr><td>Unidade</td><td>Depois de escolher um cliente, filtre por uma unidade específica dele</td></tr>\n    <tr><td>Status</td><td>Filtre por status do equipamento (ativo/inativo)</td></tr>\n  </table>\n\n  <h2 id=\"tplInv_ms4\">4. Gerar Inventário</h2>\n  <p>Depois de ajustar os filtros (ou deixar todos em branco pra ver tudo), clique em <strong>\"Gerar Inventário\"</strong> — a tabela aparece na tela, com todos os equipamentos que atendem ao filtro escolhido.</p>\n\n  <h2 id=\"tplInv_ms5\">5. Entendendo a tabela e os status</h2>\n  <p>Cada equipamento mostra o status da sua <strong>Calibração</strong> e da sua <strong>Qualificação</strong> (documentos vinculados a ele), num selo colorido:</p>\n  <table>\n    <tr><th>Selo</th><th>O que significa</th></tr>\n    <tr><td>OK (verde)</td><td>Documento válido, vencimento a mais de 30 dias</td></tr>\n    <tr><td>Vencendo (amarelo)</td><td>Vence em até 30 dias</td></tr>\n    <tr><td>Vencido (vermelho)</td><td>Já passou da validade</td></tr>\n    <tr><td>Sem documento (cinza)</td><td>Não há nenhum documento desse tipo cadastrado pra esse equipamento</td></tr>\n  </table>\n  <div class=\"callout\"><strong>Objetivo do relatório:</strong> dar uma visão rápida de quais equipamentos precisam de atenção — ordene visualmente pelos selos vermelhos e amarelos primeiro.</div>\n\n  <h2 id=\"tplInv_ms6\">6. Gerar PDF / Imprimir</h2>\n  <p>Clique em <strong>\"Gerar PDF / Imprimir\"</strong> — abre uma pré-visualização em tela cheia, formatada como documento oficial (papel A4 paisagem). Clique em <strong>\"Imprimir / Salvar PDF\"</strong> pra abrir a janela de impressão do navegador (escolha \"Salvar como PDF\" ali), ou <strong>\"Fechar\"</strong> pra voltar sem imprimir.</p>\n\n  <h2 id=\"tplInv_ms7\">7. Salvar no Drive e Documentos já Gerados</h2>\n  <p>Além de imprimir, o botão <strong>\"Salvar no Drive\"</strong> guarda uma cópia em PDF automaticamente. Na seção \"Documentos já Gerados\", use <strong>\"Buscar por cliente ou nome do arquivo\"</strong> pra encontrar um inventário salvo anteriormente, sem precisar gerar tudo de novo.</p>\n\n  <h2 id=\"tplInv_ms8\">8. Passo a passo completo</h2>\n  <ol>\n    <li>Ajuste os filtros (CNPJ, Cliente, Unidade, Status) — ou deixe todos em branco.</li>\n    <li>Clique em \"Gerar Inventário\".</li>\n    <li>Confira os selos de status na tabela.</li>\n    <li>Clique em \"Gerar PDF / Imprimir\" pra visualizar o documento final.</li>\n    <li>Imprima/salve como PDF, ou \"Salvar no Drive\" pra guardar uma cópia automática.</li>\n  </ol>\n\n  <h2 id=\"tplInv_ms9\">9. Erros comuns e o que fazer</h2>\n  <table>\n    <tr><th>O que aconteceu</th><th>O que fazer</th></tr>\n    <tr><td>\"Gere o inventário antes de imprimir\"</td><td>Clique em \"Gerar Inventário\" antes de tentar \"Gerar PDF / Imprimir\"</td></tr>\n    <tr><td>A tabela veio vazia</td><td>Confira se os filtros não estão restringindo demais (ex.: cliente errado selecionado)</td></tr>\n  </table>\n\n  <h2 id=\"tplInv_ms10\">10. Glossário</h2>\n  <table>\n    <tr><th>Termo</th><th>Explicação simples</th></tr>\n    <tr><td>Inventário</td><td>Lista completa dos equipamentos de um cliente, com status de documentação</td></tr>\n    <tr><td>Calibração / Qualificação</td><td>Os 2 tipos de documento cujo vencimento este relatório acompanha por equipamento</td></tr>\n    <tr><td>Retrato do momento</td><td>O relatório reflete a situação de quando foi gerado, não atualiza sozinho depois</td></tr>\n  </table>\n\n  <a class=\"topo-link\" onclick=\"tplInv_irParaSecaoManual_('tplInv_topoManual')\">↑ Topo</a>\n</div>`;\n}\n\nfunction tplInv_garantirOverlay_() {\n  if (document.getElementById('tplInv-print-overlay')) return;\n  var div = document.createElement('div');\n  div.id = 'tplInv-print-overlay';\n  div.innerHTML =\n    '<div class=\"tplInv-print-toolbar\">' +\n      '<span class=\"tplInv-print-toolbar-title\">Pré-visualização do Inventário</span>' +\n      '<div class=\"tplInv-print-toolbar-actions\">' +\n        '<button class=\"btn-tplInv-print\" onclick=\"tplInv_executarImpressao_()\">Imprimir / Salvar PDF</button>' +\n        '<button class=\"btn-tplInv-close\" onclick=\"tplInv_fecharOverlay_()\">Fechar</button>' +\n      '</div>' +\n    '</div>' +\n    '<div class=\"tplInv-print-scale-outer\" id=\"tplInv-print-scale-outer\"><div class=\"tplInv-print-page-wrap\" id=\"tplInv-print-page-wrap\"><div id=\"tplInv-print-content\" class=\"tplInv-prt-doc\"></div></div></div>';\n  document.body.appendChild(div);\n}\n\nfunction tplInv_ajustarEscalaPreview_() {\n  var outer = document.getElementById('tplInv-print-scale-outer');\n  var wrap = document.getElementById('tplInv-print-page-wrap');\n  if (!outer || !wrap) return;\n  wrap.style.transform = 'none';\n  var larguraDisponivel = outer.clientWidth - 32;\n  var larguraNatural = wrap.offsetWidth;\n  var alturaNatural = wrap.offsetHeight;\n  var escala = (larguraNatural > 0 && larguraDisponivel > 0) ? (larguraDisponivel / larguraNatural) : 1;\n  escala = Math.min(escala, 1.6);\n  wrap.style.transform = 'scale(' + escala + ')';\n  outer.style.height = (alturaNatural * escala) + 'px';\n}\n\nfunction tplInv_irParaTela_() {\n  var root = tplInv_root_();\n  if (!root) return;\n\n  root.innerHTML =\n    '<div class=\"header-card\" style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;\"><div><h1>Inventário de Equipamentos</h1><p>Relatório gerencial do parque de equipamentos — calibração, qualificação e documentação.</p></div><button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplInv_abrirManual_()\">Manual do Operador</button></div>' +\n    '<div class=\"panel\">' +\n      '<div class=\"inv-filters-grid\">' +\n        '<div class=\"form-group\"><label>Buscar por CNPJ</label><div style=\"display:flex;gap:6px;\"><input id=\"tplInv_cnpj_busca\" class=\"form-control\" placeholder=\"Somente números...\" onkeydown=\"if(event.key===\\x27Enter\\x27){event.preventDefault(); tplInv_buscarPorCnpj_();}\"><button type=\"button\" class=\"btn btn-secondary\" style=\"flex:0 0 auto;\" onclick=\"tplInv_buscarPorCnpj_()\">Buscar</button></div></div>' +\n        '<div class=\"form-group\"><label>Cliente</label><select id=\"tplInv_cliente_id\" class=\"form-control\" onchange=\"tplInv_aoMudarCliente_()\"><option value=\"\">Todos os clientes</option></select></div>' +\n        '<div class=\"form-group\"><label>Unidade</label><select id=\"tplInv_unidade_id\" class=\"form-control\"><option value=\"\">Todas as unidades</option></select></div>' +\n        '<div class=\"form-group\"><label>Status</label><select id=\"tplInv_status\" class=\"form-control\"><option value=\"\">Todos</option><option value=\"ATIVO\">Ativo</option><option value=\"INATIVO\">Inativo</option></select></div>' +\n        '<div class=\"form-group\"><button type=\"button\" class=\"btn btn-primary\" id=\"tplInv_btnGerar\" onclick=\"tplInv_gerar_()\">Gerar Inventário</button></div>' +\n      '</div>' +\n    '</div>' +\n    '<div id=\"tplInv-resultados\" style=\"display:none;\">' +\n      '<div class=\"inv-action-bar\">' +\n        '<div style=\"display:flex;gap:10px;\">' +\n          '<button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplInv_abrirOverlay_()\">Gerar PDF / Imprimir</button>' +\n          '<button type=\"button\" class=\"btn btn-secondary\" id=\"tplInv_btnSalvarDrive\" onclick=\"tplInv_salvarNoDrive_()\">Salvar no Drive</button>' +\n        '</div>' +\n        '<div class=\"inv-action-bar-right\" id=\"tplInv-geracao-info\"></div>' +\n      '</div>' +\n      '<div class=\"inv-kpis\" id=\"tplInv-kpis\"></div>' +\n      '<div class=\"panel\"><div style=\"overflow-x:auto;\"><table class=\"tbl\"><thead><tr>' +\n        '<th>#</th><th>TAG</th><th>Tipo</th><th>Fabricante / Modelo</th><th>Série</th><th>Setor</th><th>Unidade</th><th>Calibração</th><th>Qualificação</th><th>Status</th>' +\n      '</tr></thead><tbody id=\"tplInv-tbody\"></tbody></table></div></div>' +\n    '</div>' +\n    '<div id=\"tplInv-loading\" class=\"inv-loading\" style=\"display:none;\">Gerando inventário, aguarde...</div>' +\n    '<div id=\"tplInv-empty\" class=\"inv-empty\" style=\"display:none;\">Nenhum equipamento encontrado com os filtros selecionados.</div>' +\n    '<div class=\"panel\">' +\n      '<h2 style=\"margin:0 0 12px;font-size:14px;color:var(--text-strong);border-bottom:1px solid var(--border);padding-bottom:11px;text-transform:uppercase;\">Documentos já Gerados</h2>' +\n      '<div class=\"inv-filters-grid\" style=\"grid-template-columns:1fr auto;\">' +\n        '<div class=\"form-group\"><label>Buscar por cliente ou nome do arquivo</label><input id=\"tplInv_busca_docs\" class=\"form-control\" placeholder=\"Ex.: Hospital Exemplo...\" onkeydown=\"if(event.key===\\x27Enter\\x27){event.preventDefault(); tplInv_buscarDocumentosSalvos_();}\"></div>' +\n        '<div class=\"form-group\"><button type=\"button\" class=\"btn btn-secondary\" onclick=\"tplInv_buscarDocumentosSalvos_()\">Buscar</button></div>' +\n      '</div>' +\n      '<div id=\"tplInv_lista_docs\" style=\"margin-top:10px;font-size:12.5px;color:var(--muted);\">Use a busca acima pra encontrar inventários já salvos no Drive.</div>' +\n    '</div>';\n\n  tplInv_carregarClientes_();\n}\n\nfunction tplInv_carregarClientes_() {\n  SGO_iniciarCarregamento_();\n  google.script.run\n    .withSuccessHandler(function (res) {\n      SGO_finalizarCarregamento_();\n      if (!res || !res.success) return;\n      INV_STATE.clientes = res.items || [];\n      var sel = document.getElementById('tplInv_cliente_id');\n      if (!sel) return;\n      var opts = ['<option value=\"\">Todos os clientes</option>'];\n      INV_STATE.clientes.forEach(function (c) {\n        opts.push('<option value=\"' + tplInv_escapeHtml_(c.ID) + '\">' + tplInv_escapeHtml_(c.NOME) + '</option>');\n      });\n      sel.innerHTML = opts.join('');\n    })\n    .withFailureHandler(function (err) { SGO_finalizarCarregamento_(); console.error('tplInv_carregarClientes_: falha', err); })\n    .inventarioListarClientesAtivos(SESSION);\n}\n\nfunction tplInv_buscarPorCnpj_() {\n  var input = document.getElementById('tplInv_cnpj_busca');\n  if (!input) return;\n  var digitos = input.value.replace(/\\D/g, '');\n  if (!digitos) { alert('Digite o CNPJ (ou parte dele) pra buscar.'); return; }\n\n  var encontrado = (INV_STATE.clientes || []).find(function (c) {\n    return String(c.CNPJ || '').replace(/\\D/g, '').indexOf(digitos) !== -1;\n  });\n\n  if (!encontrado) { alert('Nenhum cliente ativo encontrado com esse CNPJ.'); return; }\n\n  var sel = document.getElementById('tplInv_cliente_id');\n  if (sel) sel.value = encontrado.ID;\n  tplInv_aoMudarCliente_();\n}\n\nfunction tplInv_aoMudarCliente_() {\n  var clienteId = document.getElementById('tplInv_cliente_id').value;\n  var sel = document.getElementById('tplInv_unidade_id');\n  if (!sel) return;\n  if (!clienteId) { sel.innerHTML = '<option value=\"\">Todas as unidades</option>'; INV_STATE.unidades = []; return; }\n  sel.innerHTML = '<option value=\"\">Carregando...</option>';\n  SGO_iniciarCarregamento_();\n  google.script.run\n    .withSuccessHandler(function (res) {\n      SGO_finalizarCarregamento_();\n      if (!res || !res.success) {\n        sel.innerHTML = '<option value=\"\">(erro ao carregar: ' + tplInv_escapeHtml_((res && res.message) || 'falha desconhecida') + ')</option>';\n        return;\n      }\n      INV_STATE.unidades = res.items || [];\n      var opts = ['<option value=\"\">Todas as unidades</option>'];\n      INV_STATE.unidades.forEach(function (u) {\n        opts.push('<option value=\"' + tplInv_escapeHtml_(u.ID) + '\">' + tplInv_escapeHtml_(u.NOME_UNIDADE) + '</option>');\n      });\n      sel.innerHTML = opts.join('');\n    })\n    .withFailureHandler(function (err) {\n      SGO_finalizarCarregamento_();\n      console.error('tplInv_aoMudarCliente_: falha', err);\n      sel.innerHTML = '<option value=\"\">(erro ao carregar: ' + tplInv_escapeHtml_((err && err.message) || err) + ')</option>';\n    })\n    .inventarioListarUnidadesAtivasPorCliente(SESSION, clienteId);\n}\n\nfunction tplInv_gerar_() {\n  var filtros = {\n    clienteId: document.getElementById('tplInv_cliente_id').value,\n    unidadeId: document.getElementById('tplInv_unidade_id').value,\n    status: document.getElementById('tplInv_status').value\n  };\n\n  var btn = document.getElementById('tplInv_btnGerar');\n  var elLoad = document.getElementById('tplInv-loading');\n  var elResult = document.getElementById('tplInv-resultados');\n  var elEmpty = document.getElementById('tplInv-empty');\n\n  if (btn) { btn.disabled = true; btn.textContent = 'Gerando...'; }\n  if (elLoad) elLoad.style.display = 'block';\n  if (elResult) elResult.style.display = 'none';\n  if (elEmpty) elEmpty.style.display = 'none';\n\n  SGO_iniciarCarregamento_();\n  google.script.run\n    .withSuccessHandler(function (res) {\n      SGO_finalizarCarregamento_();\n      if (btn) { btn.disabled = false; btn.textContent = 'Gerar Inventário'; }\n      if (elLoad) elLoad.style.display = 'none';\n\n      if (!res || !res.success) {\n        alert((res && res.message) || 'Erro ao gerar inventário.');\n        return;\n      }\n\n      INV_STATE.dados = res;\n\n      if (!res.itens || !res.itens.length) {\n        if (elEmpty) elEmpty.style.display = 'block';\n        return;\n      }\n\n      if (elResult) elResult.style.display = 'block';\n      tplInv_renderKpis_(res.indicadores);\n      tplInv_renderTabela_(res.itens);\n      tplInv_renderInfoGeracao_(res);\n    })\n    .withFailureHandler(function (err) {\n      SGO_finalizarCarregamento_();\n      if (btn) { btn.disabled = false; btn.textContent = 'Gerar Inventário'; }\n      if (elLoad) elLoad.style.display = 'none';\n      console.error('tplInv_gerar_: falha', err);\n      alert('Erro de comunicação ao gerar inventário: ' + ((err && err.message) || err));\n    })\n    .inventarioGerar(SESSION, filtros);\n}\n\nfunction tplInv_kpiCard_(cls, value, label, sub) {\n  return '<div class=\"inv-kpi ' + cls + '\">' +\n    '<div class=\"inv-kpi-value\">' + value + '</div>' +\n    '<div class=\"inv-kpi-label\">' + label + '</div>' +\n    (sub ? '<div class=\"inv-kpi-sub\">' + tplInv_escapeHtml_(sub) + '</div>' : '') +\n    '</div>';\n}\n\nfunction tplInv_renderKpis_(ind) {\n  var el = document.getElementById('tplInv-kpis');\n  if (!el) return;\n  el.innerHTML = [\n    tplInv_kpiCard_('inv-kpi-total', ind.total, 'Total de Equipamentos'),\n    tplInv_kpiCard_('inv-kpi-ok', ind.calibPct + '%', 'Calibração em Dia', ind.calibOk + ' equipamentos'),\n    tplInv_kpiCard_('inv-kpi-ok', ind.qualPct + '%', 'Qualificação em Dia', ind.qualOk + ' equipamentos'),\n    tplInv_kpiCard_('inv-kpi-warn', ind.vencendo, 'Vencendo em 30 dias'),\n    tplInv_kpiCard_('inv-kpi-danger', ind.vencidos, 'Vencidos / Irregulares'),\n    tplInv_kpiCard_('inv-kpi-muted', ind.semDoc, 'Sem Documentação')\n  ].join('');\n}\n\nfunction tplInv_classeLinha_(item) {\n  var cs = String((item.CALIBRACAO && item.CALIBRACAO.status) || '');\n  var qs = String((item.QUALIFICACAO && item.QUALIFICACAO.status) || '');\n  if (cs === 'VENCIDO' || qs === 'VENCIDO') return 'inv-row-vencido';\n  if (cs === 'VENCENDO' || qs === 'VENCENDO') return 'inv-row-vencendo';\n  if (String(item.STATUS || '').toUpperCase() === 'INATIVO') return 'inv-row-inativo';\n  return '';\n}\n\nfunction tplInv_badgeDoc_(obj) {\n  if (!obj) return '<span class=\"inv-badge inv-badge-semdoc\">--</span>';\n  var s = obj.status || 'SEM_DOC';\n  var cls = s === 'OK' ? 'inv-badge-ok' : s === 'VENCENDO' ? 'inv-badge-vencendo' : s === 'VENCIDO' ? 'inv-badge-vencido' : 'inv-badge-semdoc';\n  var label = s === 'OK' ? 'OK' : s === 'VENCENDO' ? 'Vencendo' : s === 'VENCIDO' ? 'Vencido' : 'Sem doc';\n  var venc = obj.label ? ('<div style=\"font-size:10px;color:var(--muted);margin-top:1px;\">' + tplInv_escapeHtml_(obj.label) + '</div>') : '';\n  return '<span class=\"inv-badge ' + cls + '\">' + label + '</span>' + venc;\n}\n\nfunction tplInv_badgeStatus_(status) {\n  var s = String(status || '').toUpperCase();\n  var cls = s === 'ATIVO' ? 'badge-ativo' : 'badge-inativo';\n  return '<span class=\"' + cls + '\">' + tplInv_escapeHtml_(s) + '</span>';\n}\n\nfunction tplInv_renderTabela_(itens) {\n  var tbody = document.getElementById('tplInv-tbody');\n  if (!tbody) return;\n  if (!itens || !itens.length) {\n    tbody.innerHTML = '<tr><td colspan=\"10\">Nenhum equipamento encontrado.</td></tr>';\n    return;\n  }\n  tbody.innerHTML = itens.map(function (item) {\n    var rowCls = tplInv_classeLinha_(item);\n    return '<tr class=\"' + rowCls + '\">' +\n      '<td style=\"color:var(--muted);font-size:11px;\">' + item.IDX + '</td>' +\n      '<td style=\"font-weight:800;color:var(--accent-2);\">' + tplInv_escapeHtml_(item.TAG) + '</td>' +\n      '<td>' + tplInv_escapeHtml_(item.TIPO) + '</td>' +\n      '<td style=\"font-size:12px;\">' + tplInv_escapeHtml_(item.FABRICANTE + (item.MODELO ? ' / ' + item.MODELO : '')) + '</td>' +\n      '<td style=\"font-size:11px;\">' + tplInv_escapeHtml_(item.SERIE || '--') + '</td>' +\n      '<td>' + tplInv_escapeHtml_(item.SETOR || '--') + '</td>' +\n      '<td style=\"font-size:12px;\">' + tplInv_escapeHtml_(item.UNIDADE_NOME) + '</td>' +\n      '<td>' + tplInv_badgeDoc_(item.CALIBRACAO) + '</td>' +\n      '<td>' + tplInv_badgeDoc_(item.QUALIFICACAO) + '</td>' +\n      '<td>' + tplInv_badgeStatus_(item.STATUS) + '</td>' +\n      '</tr>';\n  }).join('');\n}\n\nfunction tplInv_formatarDataHora_(iso) {\n  if (!iso) return '--';\n  try {\n    var d = new Date(iso);\n    var pad = function (n) { return String(n).padStart(2, '0'); };\n    return pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + '/' + d.getFullYear() + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());\n  } catch (e) { return String(iso); }\n}\n\nfunction tplInv_renderInfoGeracao_(dados) {\n  var el = document.getElementById('tplInv-geracao-info');\n  if (!el) return;\n  var dt = tplInv_formatarDataHora_(dados.geradoEm);\n  var cli = dados.clienteInfo ? tplInv_escapeHtml_(dados.clienteInfo.NOME_FANTASIA || dados.clienteInfo.RAZAO_SOCIAL || '') : 'Todos os clientes';\n  el.innerHTML = tplInv_escapeHtml_(dados.itens.length) + ' equipamentos &nbsp;|&nbsp; ' + cli + ' &nbsp;|&nbsp; Gerado em: ' + dt + ' por ' + tplInv_escapeHtml_(dados.geradoPor);\n}\n\nfunction tplInv_buildStandaloneHtmlParaPdf_(dados) {\n  var corpo = tplInv_buildPrintHtml_(dados);\n  var estilo = \".tplInv-prt-doc { background: #fff; font-family: 'Segoe UI', Arial, sans-serif; font-size: 10pt; color: #111; padding: 0; box-shadow: none; }\\n.tplInv-prt-header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #007b3e; padding-bottom: 10px; margin-bottom: 12px; }\\n.tplInv-prt-brand-name { font-size: 16pt; font-weight: 900; color: #007b3e; letter-spacing: .5px; }\\n.tplInv-prt-brand-slogan { font-size: 8pt; color: #555; margin-top: 2px; }\\n.tplInv-prt-header-doc { text-align: right; }\\n.tplInv-prt-doc-title { font-size: 13pt; font-weight: 800; color: #1a2e5a; text-transform: uppercase; letter-spacing: .5px; }\\n.tplInv-prt-doc-sub { font-size: 8pt; color: #555; margin-top: 2px; }\\n\\n.tplInv-prt-meta-box { background: #f8f9fa; border: 1px solid #e2e8f0; border-radius: 6px; padding: 10px 14px; margin-bottom: 14px; display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px 10px; }\\n.tplInv-prt-meta-key { font-size: 7.5pt; font-weight: 700; color: #666; text-transform: uppercase; letter-spacing: .3px; }\\n.tplInv-prt-meta-val { font-size: 9.5pt; font-weight: 600; color: #111; }\\n\\n.tplInv-prt-section-title { font-size: 8pt; font-weight: 800; color: #1a2e5a; text-transform: uppercase; letter-spacing: .8px; border-left: 3px solid #007b3e; padding-left: 7px; margin: 14px 0 8px; }\\n\\n.tplInv-prt-kpis { display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px; margin-bottom: 6px; }\\n.tplInv-prt-kpi { border: 1px solid #e2e8f0; border-radius: 6px; padding: 8px 6px; text-align: center; border-top: 3px solid; }\\n.tplInv-prt-kpi-total   { border-top-color: #1a56db; }\\n.tplInv-prt-kpi-ok1     { border-top-color: #16a34a; }\\n.tplInv-prt-kpi-ok2     { border-top-color: #0891b2; }\\n.tplInv-prt-kpi-warn    { border-top-color: #d97706; }\\n.tplInv-prt-kpi-danger  { border-top-color: #dc2626; }\\n.tplInv-prt-kpi-gray    { border-top-color: #9ca3af; }\\n.tplInv-prt-kpi-value { font-size: 18pt; font-weight: 900; line-height: 1; margin-bottom: 3px; }\\n.tplInv-prt-kpi-total  .tplInv-prt-kpi-value { color: #1a56db; }\\n.tplInv-prt-kpi-ok1    .tplInv-prt-kpi-value { color: #16a34a; }\\n.tplInv-prt-kpi-ok2    .tplInv-prt-kpi-value { color: #0891b2; }\\n.tplInv-prt-kpi-warn   .tplInv-prt-kpi-value { color: #d97706; }\\n.tplInv-prt-kpi-danger .tplInv-prt-kpi-value { color: #dc2626; }\\n.tplInv-prt-kpi-gray   .tplInv-prt-kpi-value { color: #6b7280; }\\n.tplInv-prt-kpi-label { font-size: 6.5pt; font-weight: 700; color: #555; text-transform: uppercase; letter-spacing: .3px; }\\n\\n.tplInv-prt-table { width: 100%; border-collapse: collapse; font-size: 7.5pt; }\\n.tplInv-prt-table thead tr { background: #1a2e5a; color: #fff; }\\n.tplInv-prt-table th { padding: 5px 6px; text-align: left; font-weight: 700; font-size: 7pt; text-transform: uppercase; letter-spacing: .3px; white-space: nowrap; }\\n.tplInv-prt-table td { padding: 4px 6px; border-bottom: 1px solid #f0f0f0; vertical-align: middle; }\\n.tplInv-prt-table tbody tr:nth-child(even) td { background: #f9fafb; }\\n.tplInv-prt-row-vencido  td { background: #fff0f0 !important; }\\n.tplInv-prt-row-vencendo td { background: #fffbeb !important; }\\n.tplInv-prt-row-inativo  td { opacity: .6; }\\n.tplInv-prt-tag { font-weight: 800; font-size: 8pt; color: #1a2e5a; }\\n.tplInv-prt-tipo { font-weight: 600; }\\n.tplInv-prt-badge { display: inline-block; padding: 1px 5px; border-radius: 8px; font-size: 6.5pt; font-weight: 700; white-space: nowrap; }\\n.tplInv-prt-badge-ok      { background: #d1fae5; color: #065f46; }\\n.tplInv-prt-badge-vencendo{ background: #fef3c7; color: #92400e; }\\n.tplInv-prt-badge-vencido { background: #fee2e2; color: #991b1b; }\\n.tplInv-prt-badge-semdoc  { background: #f3f4f6; color: #6b7280; }\\n.tplInv-prt-badge-ativo   { background: #d1fae5; color: #065f46; }\\n.tplInv-prt-badge-inativo { background: #f3f4f6; color: #6b7280; }\\n.tplInv-prt-footer-brand { font-weight: 700; color: #007b3e; }\";\n  return '<!doctype html><html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><title>Inventário de Equipamentos</title><style>@page { size: A4 landscape; margin: 10mm 12mm; } * { box-sizing: border-box; } body { margin: 0; background: #fff; font-family: \\x27Segoe UI\\x27, Arial, sans-serif; }' + estilo + '</style></head><body><div class=\"tplInv-prt-doc\">' + corpo + '</div></body></html>';\n}\n\nfunction tplInv_salvarNoDrive_() {\n  if (!INV_STATE.dados || !INV_STATE.dados.success) { alert('Gere o inventário antes de salvar.'); return; }\n  var btn = document.getElementById('tplInv_btnSalvarDrive');\n  if (btn) { btn.disabled = true; btn.textContent = 'Salvando...'; }\n\n  var html = tplInv_buildStandaloneHtmlParaPdf_(INV_STATE.dados);\n  var nomeCliente = INV_STATE.dados.clienteInfo\n    ? (INV_STATE.dados.clienteInfo.NOME_FANTASIA || INV_STATE.dados.clienteInfo.RAZAO_SOCIAL || '')\n    : 'Todos os clientes';\n\n  SGO_iniciarCarregamento_();\n  google.script.run\n    .withSuccessHandler(function (res) {\n      SGO_finalizarCarregamento_();\n      if (btn) { btn.disabled = false; btn.textContent = 'Salvar no Drive'; }\n      if (!res || !res.success) { alert((res && res.message) || 'Falha ao salvar no Drive.'); return; }\n      var info = document.getElementById('tplInv-geracao-info');\n      if (info) info.innerHTML += ' &nbsp;|&nbsp; Salvo: <a href=\"' + res.url + '\" target=\"_blank\" style=\"color:var(--accent-2);\">' + tplInv_escapeHtml_(res.fileName) + '</a>';\n    })\n    .withFailureHandler(function (err) {\n      SGO_finalizarCarregamento_();\n      if (btn) { btn.disabled = false; btn.textContent = 'Salvar no Drive'; }\n      console.error('tplInv_salvarNoDrive_: falha', err);\n      alert('Erro ao salvar no Drive: ' + ((err && err.message) || err));\n    })\n    .inventarioSalvarDocumento(SESSION, { html: html, cliente: nomeCliente });\n}\n\nfunction tplInv_buscarDocumentosSalvos_() {\n  var termo = document.getElementById('tplInv_busca_docs').value;\n  var lista = document.getElementById('tplInv_lista_docs');\n  if (!lista) return;\n  lista.textContent = 'Buscando...';\n\n  SGO_iniciarCarregamento_();\n  google.script.run\n    .withSuccessHandler(function (res) {\n      SGO_finalizarCarregamento_();\n      if (!res || !res.success) { lista.textContent = (res && res.message) || 'Falha ao buscar documentos.'; return; }\n      var docs = res.documentos || [];\n      if (!docs.length) { lista.textContent = 'Nenhum documento encontrado.'; return; }\n      lista.innerHTML = '<ul style=\"list-style:none;padding:0;margin:0;\">' + docs.map(function (d) {\n        return '<li style=\"padding:8px 10px;border:1px solid var(--border);border-radius:6px;margin-bottom:6px;\">' +\n          '<a href=\"' + d.url + '\" target=\"_blank\" style=\"color:var(--accent-2);font-weight:700;\">' + tplInv_escapeHtml_(d.fileName) + '</a>' +\n          ' <span style=\"color:var(--muted);\">— ' + tplInv_escapeHtml_(d.cliente) + '</span></li>';\n      }).join('') + '</ul>';\n    })\n    .withFailureHandler(function (err) {\n      SGO_finalizarCarregamento_();\n      console.error('tplInv_buscarDocumentosSalvos_: falha', err);\n      lista.textContent = 'Erro ao buscar: ' + ((err && err.message) || err);\n    })\n    .inventarioListarDocumentosSalvos(SESSION, termo);\n}\n\nfunction tplInv_abrirOverlay_() {\n  if (!INV_STATE.dados || !INV_STATE.dados.success) { alert('Gere o inventário antes de imprimir.'); return; }\n  tplInv_garantirOverlay_();\n  var overlay = document.getElementById('tplInv-print-overlay');\n  var content = document.getElementById('tplInv-print-content');\n  if (content) content.innerHTML = tplInv_buildPrintHtml_(INV_STATE.dados);\n  if (overlay) overlay.style.display = 'block';\n  document.body.classList.add('tplInv-printing');\n  tplInv_ajustarEscalaPreview_();\n  window.addEventListener('resize', tplInv_ajustarEscalaPreview_);\n}\n\nfunction tplInv_fecharOverlay_() {\n  var overlay = document.getElementById('tplInv-print-overlay');\n  if (overlay) overlay.style.display = 'none';\n  document.body.classList.remove('tplInv-printing');\n  window.removeEventListener('resize', tplInv_ajustarEscalaPreview_);\n}\n\nfunction tplInv_executarImpressao_() {\n  var wrap = document.getElementById('tplInv-print-page-wrap');\n  var outer = document.getElementById('tplInv-print-scale-outer');\n  if (wrap) wrap.style.transform = 'none';\n  if (outer) outer.style.height = 'auto';\n  document.body.classList.add('tplInv-printing');\n  window.print();\n  setTimeout(function () {\n    document.body.classList.remove('tplInv-printing');\n    tplInv_ajustarEscalaPreview_();\n  }, 1000);\n}\n\nfunction tplInv_prtKpi_(cls, value, label, sub) {\n  return '<div class=\"tplInv-prt-kpi ' + cls + '\">' +\n    '<div class=\"tplInv-prt-kpi-value\">' + value + '</div>' +\n    '<div class=\"tplInv-prt-kpi-label\">' + label + '</div>' +\n    (sub ? '<div style=\"font-size:7pt;color:#666;margin-top:1px;\">' + tplInv_escapeHtml_(sub) + '</div>' : '') +\n    '</div>';\n}\n\nfunction tplInv_prtBadgeDoc_(obj) {\n  if (!obj) return '<span class=\"tplInv-prt-badge tplInv-prt-badge-semdoc\">Sem doc</span>';\n  var s = obj.status || 'SEM_DOC';\n  var cls = s === 'OK' ? 'tplInv-prt-badge-ok' : s === 'VENCENDO' ? 'tplInv-prt-badge-vencendo' : s === 'VENCIDO' ? 'tplInv-prt-badge-vencido' : 'tplInv-prt-badge-semdoc';\n  var lbl = s === 'OK' ? 'OK' : s === 'VENCENDO' ? 'Vencendo' : s === 'VENCIDO' ? 'Vencido' : 'Sem doc';\n  var sub = obj.label ? '<div style=\"font-size:6pt;color:#777;margin-top:1px;\">' + tplInv_escapeHtml_(obj.label) + '</div>' : '';\n  return '<span class=\"tplInv-prt-badge ' + cls + '\">' + lbl + '</span>' + sub;\n}\n\nfunction tplInv_prtBadgeStatus_(status) {\n  var s = String(status || '').toUpperCase();\n  var cls = s === 'ATIVO' ? 'tplInv-prt-badge-ativo' : 'tplInv-prt-badge-inativo';\n  return '<span class=\"tplInv-prt-badge ' + cls + '\">' + tplInv_escapeHtml_(s) + '</span>';\n}\n\nfunction tplInv_prtClasseLinha_(item) {\n  var cs = String((item.CALIBRACAO && item.CALIBRACAO.status) || '');\n  var qs = String((item.QUALIFICACAO && item.QUALIFICACAO.status) || '');\n  if (cs === 'VENCIDO' || qs === 'VENCIDO') return 'tplInv-prt-row-vencido';\n  if (cs === 'VENCENDO' || qs === 'VENCENDO') return 'tplInv-prt-row-vencendo';\n  if (String(item.STATUS || '').toUpperCase() === 'INATIVO') return 'tplInv-prt-row-inativo';\n  return '';\n}\n\nfunction tplInv_buildPrintHtml_(dados) {\n  var ind = dados.indicadores;\n  var itens = dados.itens;\n  var cliObj = dados.clienteInfo;\n  var uni = dados.unidadeInfo ? tplInv_escapeHtml_(dados.unidadeInfo.NOME_UNIDADE || '') : 'Todas as unidades';\n  var dtGer = tplInv_formatarDataHora_(dados.geradoEm);\n\n  var cliNome = cliObj ? tplInv_escapeHtml_(cliObj.NOME_FANTASIA || cliObj.RAZAO_SOCIAL || '') : 'Todos os clientes';\n  var cliRazao = cliObj ? tplInv_escapeHtml_(cliObj.RAZAO_SOCIAL || '') : '';\n  var cliCnpj = cliObj ? tplInv_escapeHtml_(cliObj.CNPJ || '') : '';\n  var cliEnder = cliObj ? tplInv_escapeHtml_(cliObj.ENDERECO || '') : '';\n  var cliTel = cliObj ? tplInv_escapeHtml_(cliObj.TELEFONE || '') : '';\n  var cliEmail = cliObj ? tplInv_escapeHtml_(cliObj.EMAIL || '') : '';\n  var cliContato = cliObj ? tplInv_escapeHtml_(cliObj.CONTATO || '') : '';\n\n  var html = '<div class=\"tplInv-prt-header\">' +\n    '<div><div class=\"tplInv-prt-brand-name\">METROLABS SGO+</div><div class=\"tplInv-prt-brand-slogan\">Sistema de Gestão Operacional e Técnica</div></div>' +\n    '<div class=\"tplInv-prt-header-doc\"><div class=\"tplInv-prt-doc-title\">Inventário de Equipamentos</div><div class=\"tplInv-prt-doc-sub\">Relatório Gerencial — Engenharia Clínica</div></div>' +\n    '</div>';\n\n  if (cliObj) {\n    html += '<div style=\"background:#edf5ff;border:1px solid #bdd7f5;border-radius:8px;padding:12px 16px;margin-bottom:14px;\">';\n    html += '<div style=\"font-size:7pt;font-weight:800;color:#0b3b78;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;border-bottom:1px solid #bdd7f5;padding-bottom:5px;\">Dados do Cliente</div>';\n    html += '<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:6px 14px;\">';\n    html += '<div><div style=\"font-size:6.5pt;font-weight:700;color:#667085;text-transform:uppercase;\">Razão Social</div><div style=\"font-size:9pt;font-weight:800;color:#0b3b78;\">' + cliRazao + '</div></div>';\n    if (cliNome !== cliRazao && cliNome) html += '<div><div style=\"font-size:6.5pt;font-weight:700;color:#667085;text-transform:uppercase;\">Nome Fantasia</div><div style=\"font-size:9pt;font-weight:700;\">' + cliNome + '</div></div>';\n    if (cliCnpj) html += '<div><div style=\"font-size:6.5pt;font-weight:700;color:#667085;text-transform:uppercase;\">CNPJ</div><div style=\"font-size:9pt;font-weight:700;font-family:monospace;\">' + cliCnpj + '</div></div>';\n    if (cliEnder) html += '<div><div style=\"font-size:6.5pt;font-weight:700;color:#667085;text-transform:uppercase;\">Endereço</div><div style=\"font-size:8pt;font-weight:600;\">' + cliEnder + '</div></div>';\n    if (cliContato) html += '<div><div style=\"font-size:6.5pt;font-weight:700;color:#667085;text-transform:uppercase;\">Contato</div><div style=\"font-size:8pt;font-weight:600;\">' + cliContato + '</div></div>';\n    if (cliTel) html += '<div><div style=\"font-size:6.5pt;font-weight:700;color:#667085;text-transform:uppercase;\">Telefone</div><div style=\"font-size:8pt;font-weight:600;\">' + cliTel + '</div></div>';\n    if (cliEmail) html += '<div><div style=\"font-size:6.5pt;font-weight:700;color:#667085;text-transform:uppercase;\">E-mail</div><div style=\"font-size:8pt;font-weight:600;\">' + cliEmail + '</div></div>';\n    html += '</div></div>';\n  }\n\n  html += '<div class=\"tplInv-prt-meta-box\">' +\n    '<div><div class=\"tplInv-prt-meta-key\">Unidade</div><div class=\"tplInv-prt-meta-val\">' + uni + '</div></div>' +\n    '<div><div class=\"tplInv-prt-meta-key\">Gerado em</div><div class=\"tplInv-prt-meta-val\">' + tplInv_escapeHtml_(dtGer) + '</div></div>' +\n    '<div><div class=\"tplInv-prt-meta-key\">Gerado por</div><div class=\"tplInv-prt-meta-val\">' + tplInv_escapeHtml_(dados.geradoPor) + '</div></div>' +\n    '<div><div class=\"tplInv-prt-meta-key\">Total</div><div class=\"tplInv-prt-meta-val\">' + itens.length + ' equipamentos</div></div>' +\n    '</div>';\n\n  html += '<div class=\"tplInv-prt-section-title\">Indicadores do Parque</div>';\n  html += '<div class=\"tplInv-prt-kpis\">' +\n    tplInv_prtKpi_('tplInv-prt-kpi-total', ind.total, 'Total Equipamentos') +\n    tplInv_prtKpi_('tplInv-prt-kpi-ok1', ind.calibPct + '%', 'Calibração em Dia', ind.calibOk + ' equip.') +\n    tplInv_prtKpi_('tplInv-prt-kpi-ok2', ind.qualPct + '%', 'Qualificação em Dia', ind.qualOk + ' equip.') +\n    tplInv_prtKpi_('tplInv-prt-kpi-warn', ind.vencendo, 'Vencendo ≤30d') +\n    tplInv_prtKpi_('tplInv-prt-kpi-danger', ind.vencidos, 'Vencidos') +\n    tplInv_prtKpi_('tplInv-prt-kpi-gray', ind.semDoc, 'Sem Documentação') +\n    '</div>';\n\n  html += '<div class=\"tplInv-prt-section-title\">Listagem Detalhada (' + itens.length + ' equipamentos)</div>';\n  html += '<table class=\"tplInv-prt-table\"><thead><tr>' +\n    '<th style=\"width:22px\">#</th><th style=\"width:58px\">TAG</th><th>Tipo / Fabricante</th><th style=\"width:55px\">Série</th>' +\n    '<th>Setor / Unidade</th><th>Calibração</th><th>Qualificação</th><th>Status</th>' +\n    '</tr></thead><tbody>';\n\n  itens.forEach(function (item) {\n    var rowCls = tplInv_prtClasseLinha_(item);\n    html += '<tr class=\"' + rowCls + '\">' +\n      '<td style=\"color:#999;font-size:6.5pt;\">' + item.IDX + '</td>' +\n      '<td class=\"tplInv-prt-tag\">' + tplInv_escapeHtml_(item.TAG) + '</td>' +\n      '<td><div class=\"tplInv-prt-tipo\">' + tplInv_escapeHtml_(item.TIPO) + '</div>' +\n      '<div style=\"font-size:6.5pt;color:#666;\">' + tplInv_escapeHtml_(item.FABRICANTE) + (item.MODELO ? ' / ' + tplInv_escapeHtml_(item.MODELO) : '') + '</div></td>' +\n      '<td style=\"font-size:6.5pt;\">' + tplInv_escapeHtml_(item.SERIE || '--') + '</td>' +\n      '<td><div style=\"font-size:7.5pt;\">' + tplInv_escapeHtml_(item.SETOR || '--') + '</div>' +\n      '<div style=\"font-size:6.5pt;color:#888;\">' + tplInv_escapeHtml_(item.UNIDADE_NOME) + '</div></td>' +\n      '<td>' + tplInv_prtBadgeDoc_(item.CALIBRACAO) + '</td>' +\n      '<td>' + tplInv_prtBadgeDoc_(item.QUALIFICACAO) + '</td>' +\n      '<td>' + tplInv_prtBadgeStatus_(item.STATUS) + '</td>' +\n      '</tr>';\n  });\n\n  html += '</tbody></table>';\n\n  html += '<div style=\"margin-top:10px;display:flex;gap:12px;flex-wrap:wrap;font-size:6.5pt;color:#555;\">' +\n    '<span style=\"font-weight:700;\">Legenda:</span>' +\n    '<span style=\"background:#d1fae5;color:#065f46;padding:1px 6px;border-radius:8px;font-weight:700;\">OK</span> Dentro do prazo ' +\n    '<span style=\"background:#fef3c7;color:#92400e;padding:1px 6px;border-radius:8px;font-weight:700;\">Vencendo</span> ≤ 30 dias ' +\n    '<span style=\"background:#fee2e2;color:#991b1b;padding:1px 6px;border-radius:8px;font-weight:700;\">Vencido</span> Fora do prazo ' +\n    '<span style=\"background:#f3f4f6;color:#6b7280;padding:1px 6px;border-radius:8px;font-weight:700;\">Sem doc</span> Sem documentação' +\n    '</div>';\n\n  html += '<div style=\"margin-top:14px;border-top:2px solid #e2e8f0;padding-top:10px;\">' +\n    '<div style=\"font-size:8pt;font-weight:800;\" class=\"tplInv-prt-footer-brand\">METROLABS SGO+ — Sistema de Gestão Operacional e Técnica</div>' +\n    '<div style=\"font-size:7pt;color:#777;font-style:italic;\">Documento gerado em ' + tplInv_escapeHtml_(dtGer) + ' por ' + tplInv_escapeHtml_(dados.geradoPor) + '.</div>' +\n    '</div>';\n\n  return html;\n}\n</script>\n";

